  ["805b501ade850228"] = { "Ehi, Belm! Dammi un boccale di ⟦Thunder Ale=Birra del Tuono⟧, e uno per {name}, <un/una> <buon/buona> <amico/amica> <mio/mia>.", "." },
  ["805fe3b2b39ca71a"] = { "Che peccato: a quanto pare abbiamo raccolto tutte le bende di telamagica necessarie. Forse puoi andare a venderle alla casa d'aste? Ma prima di andare, fai <il/la> <bravo/brava> <ragazzo/ragazza> e chiedi agli altri raccoglitori presenti. Potrebbero avere una commissione da affidarti.", "." },
  ["806fcde6135a7de7"] = { "Il nome Earthshatter appartiene alla mia famiglia da centinaia di anni. E come mio padre e suo padre prima di lui, anch'io ho ereditato il diritto di creare le vesti che portano il mio nome.", "." },
  ["80719a23b9b26cbf"] = { "Non hai mai avuto una vera cavalcatura finché non hai preso le redini di un montone di montagna di Barak Tor'ol di razza pregiata, <amico/amica> <mio/mia>. Prego, esamina pure questi splendidi compagni per ogni avventuriero. Ti serviranno bene, credimi.", "." },
  ["80749519ffaf7e29"] = { "I trogg... non smettono mai di arrivare. Muori, trogg! Muori!", "." },
