  ["80a00226fc2fba8f"] = { "Ora solo il rinomato dottor Gregory Victor può migliorare la tua abilità. Lo trovi negli ⟦Arathi Highlands=Altopiani d'Arathi⟧, a ⟦Hammerfall=Requie del Martello⟧.", "." },
  ["80a5448c7843fd4b"] = { "Quegli elementali ladri sono su per il sentiero, da questa parte. Buona fortuna, {name}.", "." },
  ["80ac03a1d4109483"] = { "Spiriti maledetti! Lasciate andare il passato! Il ⟦Crystal of Zin-Malor=Cristallo di Zin-Malor⟧ non vi vincola più!", "." },
